<!DOCTYPE html>
<html lang="hu">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Autonóm Kutatóágens | Research AI</title>
    <link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=SF+Pro+Display:wght@300;400;500;600;700&display=swap">
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        :root {
            --color-bg: #000000;
            --color-surface: #1d1d1f;
            --color-surface-light: #2d2d2f;
            --color-text: #f5f5f7;
            --color-text-secondary: #a1a1a6;
            --color-accent: #0071e3;
            --color-accent-hover: #0077ed;
            --spacing-xs: 8px;
            --spacing-sm: 12px;
            --spacing-md: 20px;
            --spacing-lg: 32px;
            --spacing-xl: 48px;
            --radius-sm: 12px;
            --radius-md: 18px;
            --radius-lg: 24px;
            --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }

        body {
            font-family: 'SF Pro Display', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background: var(--color-bg);
            color: var(--color-text);
            min-height: 100vh;
            padding: var(--spacing-md);
            line-height: 1.6;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
        }

        .container {
            max-width: 1680px;
            margin: 0 auto;
        }

        .header {
            background: rgba(29, 29, 31, 0.72);
            backdrop-filter: blur(20px) saturate(180%);
            -webkit-backdrop-filter: blur(20px) saturate(180%);
            padding: var(--spacing-lg);
            border-radius: var(--radius-lg);
            margin-bottom: var(--spacing-md);
            border: 1px solid rgba(255, 255, 255, 0.1);
            animation: fadeIn 0.6s ease-out;
        }

        @keyframes fadeIn {
            from {
                opacity: 0;
                transform: translateY(-20px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        h1 {
            font-size: clamp(32px, 5vw, 56px);
            font-weight: 700;
            letter-spacing: -0.015em;
            background: linear-gradient(135deg, #f5f5f7 0%, #a1a1a6 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            margin-bottom: var(--spacing-sm);
        }

        .subtitle {
            font-size: 17px;
            color: var(--color-text-secondary);
            font-weight: 400;
            letter-spacing: -0.01em;
        }

        .main-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 600px), 1fr));
            gap: var(--spacing-md);
            margin-bottom: var(--spacing-md);
        }

        .card {
            background: rgba(29, 29, 31, 0.72);
            backdrop-filter: blur(20px) saturate(180%);
            -webkit-backdrop-filter: blur(20px) saturate(180%);
            padding: var(--spacing-lg);
            border-radius: var(--radius-lg);
            border: 1px solid rgba(255, 255, 255, 0.1);
            transition: var(--transition);
            animation: fadeIn 0.6s ease-out;
            animation-fill-mode: backwards;
        }

        .card:nth-child(1) { animation-delay: 0.1s; }
        .card:nth-child(2) { animation-delay: 0.2s; }
        .card:nth-child(3) { animation-delay: 0.3s; }
        .card:nth-child(4) { animation-delay: 0.4s; }

        .card:hover {
            transform: translateY(-4px);
            border-color: rgba(255, 255, 255, 0.2);
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
        }

        .card h2 {
            font-size: 24px;
            font-weight: 600;
            margin-bottom: var(--spacing-md);
            letter-spacing: -0.01em;
            display: flex;
            align-items: center;
            gap: var(--spacing-sm);
        }

        .mode-toggle {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--spacing-sm);
            margin-bottom: var(--spacing-md);
            padding: 4px;
            background: rgba(255, 255, 255, 0.05);
            border-radius: var(--radius-sm);
        }

        .mode-btn {
            padding: var(--spacing-md);
            border: none;
            background: transparent;
            border-radius: calc(var(--radius-sm) - 4px);
            cursor: pointer;
            transition: var(--transition);
            font-size: 15px;
            font-weight: 500;
            color: var(--color-text-secondary);
            position: relative;
            overflow: hidden;
        }

        .mode-btn::before {
            content: '';
            position: absolute;
            inset: 0;
            background: linear-gradient(135deg, rgba(0, 113, 227, 0.1) 0%, rgba(0, 119, 237, 0.05) 100%);
            opacity: 0;
            transition: var(--transition);
        }

        .mode-btn:hover::before {
            opacity: 1;
        }

        .mode-btn.active {
            background: var(--color-accent);
            color: white;
            box-shadow: 0 4px 12px rgba(0, 113, 227, 0.3);
        }

        .mode-btn div {
            font-size: 12px;
            font-weight: 400;
            margin-top: 4px;
            opacity: 0.8;
        }

        .input-group {
            margin-bottom: var(--spacing-md);
        }

        label {
            display: block;
            font-size: 14px;
            font-weight: 500;
            margin-bottom: var(--spacing-xs);
            color: var(--color-text);
            letter-spacing: -0.01em;
        }

        textarea, input[type="text"], input[type="number"] {
            width: 100%;
            padding: var(--spacing-sm);
            background: rgba(255, 255, 255, 0.05);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: var(--radius-sm);
            font-size: 15px;
            color: var(--color-text);
            font-family: inherit;
            transition: var(--transition);
        }

        textarea:focus, input:focus {
            outline: none;
            background: rgba(255, 255, 255, 0.08);
            border-color: var(--color-accent);
            box-shadow: 0 0 0 4px rgba(0, 113, 227, 0.1);
        }

        textarea {
            min-height: 120px;
            resize: vertical;
        }

        .settings-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--spacing-md);
        }

        button {
            background: var(--color-accent);
            color: white;
            border: none;
            padding: var(--spacing-md) var(--spacing-lg);
            border-radius: 980px;
            font-size: 16px;
            font-weight: 500;
            cursor: pointer;
            transition: var(--transition);
            width: 100%;
            position: relative;
            overflow: hidden;
        }

        button::before {
            content: '';
            position: absolute;
            inset: 0;
            background: linear-gradient(180deg, rgba(255,255,255,0.2) 0%, transparent 100%);
            opacity: 0;
            transition: var(--transition);
        }

        button:hover {
            background: var(--color-accent-hover);
            transform: scale(1.02);
            box-shadow: 0 8px 24px rgba(0, 113, 227, 0.4);
        }

        button:hover::before {
            opacity: 1;
        }

        button:active {
            transform: scale(0.98);
        }

        button:disabled {
            opacity: 0.4;
            cursor: not-allowed;
            transform: none;
        }

        .upload-area {
            border: 2px dashed rgba(255, 255, 255, 0.2);
            border-radius: var(--radius-md);
            padding: var(--spacing-xl);
            text-align: center;
            cursor: pointer;
            transition: var(--transition);
            margin-bottom: var(--spacing-md);
            background: rgba(255, 255, 255, 0.02);
        }

        .upload-area:hover {
            border-color: var(--color-accent);
            background: rgba(0, 113, 227, 0.05);
            transform: scale(1.01);
        }

        .upload-area.dragover {
            border-color: var(--color-accent);
            background: rgba(0, 113, 227, 0.1);
            transform: scale(1.02);
        }

        .progress-container {
            margin-top: var(--spacing-md);
            display: none;
            animation: fadeIn 0.4s ease-out;
        }

        .progress-container.active {
            display: block;
        }

        .progress-bar {
            height: 4px;
            background: rgba(255, 255, 255, 0.1);
            border-radius: 2px;
            overflow: hidden;
            margin-bottom: var(--spacing-sm);
        }

        .progress-fill {
            height: 100%;
            background: linear-gradient(90deg, var(--color-accent) 0%, #0077ed 100%);
            transition: width 0.4s cubic-bezier(0.4, 0, 0.2, 1);
            width: 0%;
            box-shadow: 0 0 20px rgba(0, 113, 227, 0.5);
        }

        .progress-text {
            color: var(--color-text-secondary);
            font-size: 13px;
            display: flex;
            justify-content: space-between;
            font-weight: 500;
        }

        .status-badge {
            display: inline-block;
            padding: 4px 12px;
            border-radius: 12px;
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.05em;
        }

        .status-pending { background: rgba(255, 204, 0, 0.2); color: #ffd60a; }
        .status-running { background: rgba(0, 113, 227, 0.2); color: #0a84ff; }
        .status-completed { background: rgba(48, 209, 88, 0.2); color: #32d74b; }
        .status-failed { background: rgba(255, 69, 58, 0.2); color: #ff453a; }

        .action-log {
            max-height: 400px;
            overflow-y: auto;
            margin-top: var(--spacing-md);
        }

        .action-log::-webkit-scrollbar {
            width: 8px;
        }

        .action-log::-webkit-scrollbar-track {
            background: rgba(255, 255, 255, 0.05);
            border-radius: 4px;
        }

        .action-log::-webkit-scrollbar-thumb {
            background: rgba(255, 255, 255, 0.2);
            border-radius: 4px;
        }

        .action-item {
            padding: var(--spacing-sm);
            border-left: 2px solid var(--color-accent);
            background: rgba(0, 113, 227, 0.05);
            margin-bottom: var(--spacing-sm);
            border-radius: 8px;
            transition: var(--transition);
            animation: slideIn 0.3s ease-out;
        }

        @keyframes slideIn {
            from {
                opacity: 0;
                transform: translateX(-20px);
            }
            to {
                opacity: 1;
                transform: translateX(0);
            }
        }

        .action-item:hover {
            background: rgba(0, 113, 227, 0.1);
            transform: translateX(4px);
        }

        .action-item .timestamp {
            font-size: 11px;
            color: var(--color-text-secondary);
            margin-bottom: 4px;
        }

        .action-item .tool {
            font-weight: 600;
            color: var(--color-accent);
            font-size: 13px;
        }

        .action-item .action {
            color: var(--color-text);
            font-size: 13px;
            margin-top: 4px;
        }

        .sources-list {
            max-height: 500px;
            overflow-y: auto;
            margin-top: var(--spacing-md);
        }

        .source-item {
            padding: var(--spacing-sm);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: var(--radius-sm);
            margin-bottom: var(--spacing-sm);
            transition: var(--transition);
            background: rgba(255, 255, 255, 0.02);
        }

        .source-item:hover {
            background: rgba(255, 255, 255, 0.05);
            border-color: rgba(255, 255, 255, 0.2);
            transform: translateX(4px);
        }

        .source-title {
            font-weight: 600;
            margin-bottom: 6px;
        }

        .source-title a {
            color: var(--color-accent);
            text-decoration: none;
            transition: var(--transition);
        }

        .source-title a:hover {
            color: var(--color-accent-hover);
        }

        .source-meta {
            display: flex;
            gap: var(--spacing-md);
            font-size: 12px;
            color: var(--color-text-secondary);
            margin-bottom: var(--spacing-xs);
        }

        .source-excerpt {
            font-size: 13px;
            color: var(--color-text-secondary);
            line-height: 1.5;
        }

        .reliability-badge {
            display: inline-block;
            padding: 2px 8px;
            border-radius: 8px;
            font-size: 11px;
            font-weight: 600;
        }

        .reliability-high { background: rgba(48, 209, 88, 0.2); color: #32d74b; }
        .reliability-medium { background: rgba(255, 204, 0, 0.2); color: #ffd60a; }
        .reliability-low { background: rgba(255, 69, 58, 0.2); color: #ff453a; }

        .report-viewer {
            background: rgba(29, 29, 31, 0.72);
            backdrop-filter: blur(20px) saturate(180%);
            -webkit-backdrop-filter: blur(20px) saturate(180%);
            padding: var(--spacing-lg);
            border-radius: var(--radius-lg);
            border: 1px solid rgba(255, 255, 255, 0.1);
            margin-top: var(--spacing-md);
            display: none;
            animation: fadeIn 0.6s ease-out;
        }

        .report-viewer.active {
            display: block;
        }

        .report-content {
            max-height: 600px;
            overflow-y: auto;
            padding: var(--spacing-md);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: var(--radius-sm);
            background: rgba(0, 0, 0, 0.3);
            font-size: 14px;
            line-height: 1.8;
        }

        .report-content h1, .report-content h2, .report-content h3 {
            color: var(--color-text);
            margin-top: var(--spacing-md);
            margin-bottom: var(--spacing-sm);
            font-weight: 600;
        }

        .report-content p {
            margin-bottom: var(--spacing-sm);
        }

        .report-content a {
            color: var(--color-accent);
            text-decoration: none;
        }

        .report-content a:hover {
            color: var(--color-accent-hover);
            text-decoration: underline;
        }

        .empty-state {
            text-align: center;
            padding: var(--spacing-xl);
            color: var(--color-text-secondary);
        }

        .spinner {
            border: 3px solid rgba(255, 255, 255, 0.1);
            border-top: 3px solid var(--color-accent);
            border-radius: 50%;
            width: 40px;
            height: 40px;
            animation: spin 1s linear infinite;
            margin: var(--spacing-md) auto;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }

        .notification {
            position: fixed;
            top: var(--spacing-md);
            right: var(--spacing-md);
            background: rgba(29, 29, 31, 0.95);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            padding: var(--spacing-md) var(--spacing-lg);
            border-radius: var(--radius-md);
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
            z-index: 1000;
            display: none;
            max-width: 400px;
            border: 1px solid rgba(255, 255, 255, 0.1);
        }

        .notification.active {
            display: block;
            animation: slideInRight 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        }

        @keyframes slideInRight {
            from {
                transform: translateX(400px);
                opacity: 0;
            }
            to {
                transform: translateX(0);
                opacity: 1);
            }
        }

        .notification.success { border-left: 4px solid #32d74b; }
        .notification.error { border-left: 4px solid #ff453a; }
        .notification.info { border-left: 4px solid var(--color-accent); }

        .step-indicator {
            background: rgba(0, 113, 227, 0.1);
            padding: var(--spacing-sm);
            border-radius: var(--radius-sm);
            margin-bottom: var(--spacing-md);
            font-size: 14px;
            display: none;
            border: 1px solid rgba(0, 113, 227, 0.2);
        }

        .step-indicator.active {
            display: block;
            animation: fadeIn 0.3s ease-out;
        }

        .step-indicator strong {
            color: var(--color-text);
        }

        @media (max-width: 768px) {
            .main-grid {
                grid-template-columns: 1fr;
            }

            .settings-row {
                grid-template-columns: 1fr;
            }

            h1 {
                font-size: 36px;
            }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                animation-iteration-count: 1 !important;
                transition-duration: 0.01ms !important;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>🔍 Autonóm Kutatóágens</h1>
            <p class="subtitle">Powered by Exa AI • Cerebras • Qwen Thinking • Grok 4</p>
        </div>

        <div class="main-grid">
            <div class="card">
                <h2>⚙️ Konfiguráció</h2>

                <div class="mode-toggle">
                    <button class="mode-btn active" data-mode="sima" onclick="selectMode('sima')">
                        ⚡ Sima Mód
                        <div>100+ forrás, gyors</div>
                    </button>
                    <button class="mode-btn" data-mode="kutatas" onclick="selectMode('kutatas')">
                        🔬 Kutatás Mód
                        <div>Mély elemzés, max 60 perc</div>
                    </button>
                </div>

                <div class="input-group">
                    <label for="query">Kutatási Kérdés</label>
                    <textarea id="query" placeholder="Add meg a kutatási kérdést vagy témát..."></textarea>
                </div>

                <div class="settings-row">
                    <div class="input-group">
                        <label for="time-limit">Időkeret (perc)</label>
                        <input type="number" id="time-limit" value="10" min="1" max="60">
                    </div>
                    <div class="input-group">
                        <label for="max-sources">Maximum források</label>
                        <input type="number" id="max-sources" value="100" min="10" max="500">
                    </div>
                </div>

                <div class="upload-area" id="upload-area">
                    <div style="font-size: 48px; margin-bottom: 10px;">📄</div>
                    <div><strong>Húzd ide a fájlokat</strong></div>
                    <div style="font-size: 13px; margin-top: 6px; opacity: 0.7;">
                        PDF, DOCX, TXT, CSV, XLSX, PNG, JPG, kód
                    </div>
                    <input type="file" id="file-input" multiple style="display: none;">
                </div>

                <div class="file-list" id="file-list"></div>

                <button onclick="startResearch()" id="start-btn">
                    🚀 Kutatás Indítása
                </button>

                <div class="progress-container" id="progress-container">
                    <div class="step-indicator" id="step-indicator">
                        <strong>Aktuális lépés:</strong> <span id="current-step">Inicializálás...</span>
                    </div>
                    <div class="progress-bar">
                        <div class="progress-fill" id="progress-fill"></div>
                    </div>
                    <div class="progress-text">
                        <span id="progress-percent">0%</span>
                        <span id="job-status">Inicializálás...</span>
                    </div>
                </div>
            </div>

            <div class="card">
                <h2>📋 Action Log</h2>
                <div class="action-log" id="action-log">
                    <div class="empty-state">
                        <p>Még nincs aktív kutatás</p>
                    </div>
                </div>
            </div>
        </div>

        <div class="main-grid">
            <div class="card">
                <h2>🌐 Források</h2>
                <div class="sources-list" id="sources-list">
                    <div class="empty-state">
                        <p>Források megjelennek itt a kutatás során</p>
                    </div>
                </div>
            </div>

            <div class="card">
                <h2>📊 Statisztika</h2>
                <div id="stats" style="font-size: 14px;">
                    <p style="margin-bottom: 10px;"><strong>Aktív feladat:</strong> <span id="stat-job">Nincs</span></p>
                    <p style="margin-bottom: 10px;"><strong>Mód:</strong> <span id="stat-mode">-</span></p>
                    <p style="margin-bottom: 10px;"><strong>Források száma:</strong> <span id="stat-sources">0</span></p>
                    <p style="margin-bottom: 10px;"><strong>Lépések száma:</strong> <span id="stat-actions">0</span></p>
                    <p style="margin-bottom: 10px;"><strong>Állapot:</strong> <span id="stat-status">-</span></p>
                </div>
            </div>
        </div>

        <div class="report-viewer" id="report-viewer">
            <h2>📄 Kutatási Jelentés</h2>
            <div class="report-content" id="report-content"></div>
            <div style="display: flex; gap: 12px; margin-top: 20px;">
                <button onclick="downloadReport('markdown')">⬇️ Letöltés (Markdown)</button>
                <button onclick="copyReport()">📋 Másolás</button>
            </div>
        </div>
    </div>

    <div class="notification" id="notification"></div>

    <script>
        let currentMode = 'sima';
        let currentJobId = null;
        let wsConnection = null;
        let uploadedFiles = [];

        function selectMode(mode) {
            currentMode = mode;
            document.querySelectorAll('.mode-btn').forEach(btn => {
                btn.classList.remove('active');
            });
            document.querySelector(`[data-mode="${mode}"]`).classList.add('active');

            if (mode === 'kutatas') {
                document.getElementById('time-limit').value = 30;
                document.getElementById('max-sources').value = 200;
            } else {
                document.getElementById('time-limit').value = 10;
                document.getElementById('max-sources').value = 100;
            }
        }

        const uploadArea = document.getElementById('upload-area');
        const fileInput = document.getElementById('file-input');

        uploadArea.addEventListener('click', () => fileInput.click());

        uploadArea.addEventListener('dragover', (e) => {
            e.preventDefault();
            uploadArea.classList.add('dragover');
        });

        uploadArea.addEventListener('dragleave', () => {
            uploadArea.classList.remove('dragover');
        });

        uploadArea.addEventListener('drop', async (e) => {
            e.preventDefault();
            uploadArea.classList.remove('dragover');
            const files = Array.from(e.dataTransfer.files);
            await handleFiles(files);
        });

        fileInput.addEventListener('change', async (e) => {
            const files = Array.from(e.target.files);
            await handleFiles(files);
        });

        async function handleFiles(files) {
            for (const file of files) {
                const formData = new FormData();
                formData.append('file', file);

                try {
                    const response = await fetch('/upload', {
                        method: 'POST',
                        body: formData
                    });

                    if (response.ok) {
                        const data = await response.json();
                        uploadedFiles.push(data);
                        showNotification(`Fájl feltöltve: ${file.name}`, 'success');
                        updateFileList();
                    } else {
                        showNotification(`Feltöltés sikertelen: ${file.name}`, 'error');
                    }
                } catch (error) {
                    showNotification(`Hiba: ${error.message}`, 'error');
                }
            }
        }

        function updateFileList() {
            const fileList = document.getElementById('file-list');
            if (uploadedFiles.length === 0) {
                fileList.innerHTML = '';
                return;
            }

            fileList.innerHTML = uploadedFiles.map((file, index) => `
                <div style="padding: 8px; background: rgba(255,255,255,0.05); border-radius: 8px; margin-bottom: 6px; font-size: 13px; display: flex; justify-content: space-between; align-items: center;">
                    <span>📄 ${file.filename} (${(file.size / 1024).toFixed(1)} KB)</span>
                    <span style="color: #ff453a; cursor: pointer; font-weight: 600;" onclick="removeFile(${index})">✕</span>
                </div>
            `).join('');
        }

        function removeFile(index) {
            uploadedFiles.splice(index, 1);
            updateFileList();
        }

        async function startResearch() {
            const query = document.getElementById('query').value.trim();
            if (!query) {
                showNotification('Adj meg egy kutatási kérdést!', 'error');
                return;
            }

            const timeLimit = parseInt(document.getElementById('time-limit').value);
            const maxSources = parseInt(document.getElementById('max-sources').value);

            const requestData = {
                mode: currentMode,
                prompt: query,
                time_limit_minutes: timeLimit,
                max_sources: maxSources,
                exclude_domains: [],
                prefer_recent: true
            };

            try {
                document.getElementById('start-btn').disabled = true;
                document.getElementById('start-btn').textContent = '⏳ Indítás...';

                const response = await fetch('/query', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(requestData)
                });

                if (!response.ok) {
                    throw new Error('Hiba a kutatás indításakor');
                }

                const data = await response.json();
                currentJobId = data.job_id;

                showNotification('Kutatás elindítva!', 'success');

                document.getElementById('progress-container').classList.add('active');
                document.getElementById('step-indicator').classList.add('active');

                document.getElementById('stat-job').textContent = currentJobId;
                document.getElementById('stat-mode').textContent = currentMode.toUpperCase();

                connectWebSocket(currentJobId);
                startPolling(currentJobId);

            } catch (error) {
                showNotification(`Hiba: ${error.message}`, 'error');
                document.getElementById('start-btn').disabled = false;
                document.getElementById('start-btn').textContent = '🚀 Kutatás Indítása';
            }
        }

        function connectWebSocket(jobId) {
            const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
            const wsUrl = `${protocol}//${window.location.host}/ws/${jobId}`;

            wsConnection = new WebSocket(wsUrl);

            wsConnection.onmessage = (event) => {
                const data = JSON.parse(event.data);

                if (data.type === 'status_update') {
                    updateProgress(data.progress, data.current_step, data.status);
                    document.getElementById('stat-sources').textContent = data.sources_count;
                    document.getElementById('stat-actions').textContent = data.action_logs_count;
                } else if (data.type === 'final_result') {
                    if (data.status === 'completed' && data.report_available) {
                        loadReport(jobId);
                    }
                }
            };

            wsConnection.onerror = () => {
                console.log('WebSocket error, using polling');
            };
        }

        async function startPolling(jobId) {
            const pollInterval = setInterval(async () => {
                try {
                    const [statusRes, logRes, sourcesRes] = await Promise.all([
                        fetch(`/status/${jobId}`),
                        fetch(`/log/${jobId}`),
                        fetch(`/sources/${jobId}`)
                    ]);

                    const status = await statusRes.json();
                    const logs = await logRes.json();
                    const sources = await sourcesRes.json();

                    updateProgress(status.progress, status.current_step, status.status);
                    updateActionLog(logs.action_logs);
                    updateSources(sources.sources);

                    document.getElementById('stat-status').textContent = status.status.toUpperCase();

                    if (status.status === 'completed' || status.status === 'failed') {
                        clearInterval(pollInterval);
                        document.getElementById('start-btn').disabled = false;
                        document.getElementById('start-btn').textContent = '🚀 Kutatás Indítása';

                        if (status.status === 'completed') {
                            loadReport(jobId);
                            showNotification('Kutatás befejezve!', 'success');
                        } else {
                            showNotification(`Kutatás sikertelen: ${status.error}`, 'error');
                        }

                        if (wsConnection) {
                            wsConnection.close();
                        }
                    }
                } catch (error) {
                    console.error('Polling error:', error);
                }
            }, 2000);
        }

        function updateProgress(progress, currentStep, status) {
            const progressPercent = Math.round(progress * 100);
            document.getElementById('progress-fill').style.width = `${progressPercent}%`;
            document.getElementById('progress-percent').textContent = `${progressPercent}%`;
            document.getElementById('job-status').textContent = status.toUpperCase();
            document.getElementById('current-step').textContent = currentStep;
        }

        function updateActionLog(logs) {
            const actionLog = document.getElementById('action-log');

            if (logs.length === 0) {
                return;
            }

            actionLog.innerHTML = logs.map(log => `
                <div class="action-item">
                    <div class="timestamp">${new Date(log.timestamp).toLocaleString('hu-HU')}</div>
                    <div class="tool">${log.tool}</div>
                    <div class="action">${log.action}</div>
                    <div style="margin-top: 6px; color: var(--color-text-secondary); font-size: 12px;">${log.result_summary}</div>
                    ${log.confidence ? `<span style="display: inline-block; margin-top: 6px; padding: 4px 8px; background: rgba(0, 113, 227, 0.2); border-radius: 8px; font-size: 11px; font-weight: 600; color: var(--color-accent);">Megbízhatóság: ${(log.confidence * 100).toFixed(0)}%</span>` : ''}
                </div>
            `).reverse().join('');
        }

        function updateSources(sources) {
            const sourcesList = document.getElementById('sources-list');

            if (sources.length === 0) {
                return;
            }

            document.getElementById('stat-sources').textContent = sources.length;

            sourcesList.innerHTML = sources.slice(0, 50).map(source => `
                <div class="source-item">
                    <div class="source-title">
                        <a href="${source.url}" target="_blank" rel="noopener noreferrer">${source.title}</a>
                    </div>
                    <div class="source-meta">
                        <span class="reliability-badge reliability-${source.reliability}">${source.reliability.toUpperCase()}</span>
                        <span>Pontszám: ${(source.authority_score * 100).toFixed(0)}%</span>
                        ${source.date ? `<span>📅 ${source.date}</span>` : ''}
                    </div>
                    <div class="source-excerpt">${source.excerpt}</div>
                </div>
            `).join('');
        }

        async function loadReport(jobId) {
            try {
                const response = await fetch(`/report/${jobId}`);
                if (!response.ok) {
                    throw new Error('Jelentés betöltése sikertelen');
                }

                const data = await response.json();
                const reportContent = document.getElementById('report-content');

                reportContent.innerHTML = marked ? marked.parse(data.report) : `<pre>${data.report}</pre>`;

                document.getElementById('report-viewer').classList.add('active');

                document.getElementById('report-viewer').scrollIntoView({ behavior: 'smooth' });
            } catch (error) {
                showNotification(`Jelentés betöltési hiba: ${error.message}`, 'error');
            }
        }

        async function downloadReport(format) {
            if (!currentJobId) return;

            try {
                const response = await fetch(`/report/${currentJobId}?format=${format}`);
                const data = await response.json();

                const blob = new Blob([data.report], { type: 'text/markdown' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `research_report_${currentJobId}.md`;
                a.click();
                URL.revokeObjectURL(url);

                showNotification('Jelentés letöltve!', 'success');
            } catch (error) {
                showNotification(`Letöltési hiba: ${error.message}`, 'error');
            }
        }

        function copyReport() {
            const reportContent = document.getElementById('report-content').innerText;
            navigator.clipboard.writeText(reportContent).then(() => {
                showNotification('Jelentés vágólapra másolva!', 'success');
            }).catch(() => {
                showNotification('Másolás sikertelen', 'error');
            });
        }

        function showNotification(message, type = 'info') {
            const notification = document.getElementById('notification');
            notification.textContent = message;
            notification.className = `notification ${type} active`;

            setTimeout(() => {
                notification.classList.remove('active');
            }, 4000);
        }
    </script>
    <script src="https://cdn.jsdelivr.net/npm/marked/marked.min.js"></script>
</body>
